import type { TLinks } from "./types.ts";

import { isObject } from "@eoussama/core";
import * as z from "zod/mini";

import { DAY_MS } from "./time.ts";



/*
 * The one definition of links.json: the TypeScript types, the check of the file and the
 * editor schema (links.schema.json, generated by `pnpm schema`) all come from here.
 *
 * The file is a tree. A key is either a field of the link at that spot (url, mailto, ...),
 * a child, whose key extends the short path (github → dx is to.ouss.es/github/dx),
 * or a group in parentheses, which only organizes the file ((design) → dribbble is still
 * to.ouss.es/dribbble). The tree is flattened into one map of short paths to links.
 */

/** One part of a short path: lowercase letters, digits and dashes, starting with a letter or digit. */
const SEGMENT = "[a-z0-9][a-z0-9-]*";

/**
 * The longest a whole short path (`github/dx`) can be. It keeps every QR code at
 * version 6 or below, where the logo never covers an alignment pattern, quick to draw,
 * and every path whole in the analytics index (96 bytes).
 */
export const MAX_PATH = 32;

const SEGMENT_RULE = "Keys must be lowercase letters, digits and dashes, starting with a letter or digit, or a group in parentheses like (design).";
const PATH_RULE = `A short path can be at most ${MAX_PATH} characters, so its QR code stays small and reliable.`;

const email = z.email({ error: "Must be an email address." });

// Text with a lone surrogate is valid JSON but can't be percent-encoded: it would crash every click.
const text = z.string().check(z.refine(value => value.isWellFormed(), { error: "Must not contain broken Unicode characters." }));
const addresses = z.union([email, z.array(email).check(z.minLength(1, { error: "Must list at least one address." }))], { error: "Must be an email address, or a list of them." });

/** When a link stops working: a day (the link works through that whole day, UTC) or an exact time. */
const expires = z.optional(z.union([z.iso.date(), z.iso.datetime({ offset: true })], { error: "Must be a date (2026-12-31) or a date and time (2026-12-31T18:00:00Z)." })
  .register(z.globalRegistry, { description: "When the link stops working: a day (it works through that whole day, UTC) or an exact time. After that, it goes to the 404 page." }));

/** The fields of a link to a web page. */
const urlFields = {
  // The scheme is lowercase on both sides: JSON Schema patterns can't ignore case.
  url: z.httpUrl({ error: "Must be an absolute http or https URL.", abort: true })
    .check(z.regex(/^https?:\/\//, { error: "Must start with http:// or https://, in lowercase." }))
    .register(z.globalRegistry, { description: "The target, an absolute http or https URL.", format: "uri" }),
  permanent: z.optional(z.boolean().register(z.globalRegistry, { description: "Answer with 301 (cached by browsers) instead of 302." })),
  expires,
};

/** The fields of a link that opens a prefilled email. */
const mailtoFields = {
  mailto: z.email({ error: "Must be an email address." }).register(z.globalRegistry, { description: "The recipient's address." }),
  expires,
  subject: z.optional(text),
  body: z.optional(text),
  cc: z.optional(addresses),
  bcc: z.optional(addresses),
};

/** A link to a web page. */
export const urlLinkSchema = z.strictObject(urlFields).check(z.refine(link => !(link.permanent === true && link.expires !== undefined), {
  // Browsers keep a 301 indefinitely, so a permanent link would keep working after it expires.
  error: "A link can't be both permanent and expiring: browsers would keep the permanent redirect after it expires.",
  path: ["permanent"],
}));

/** A link that opens a prefilled email. */
export const mailtoLinkSchema = z.strictObject(mailtoFields);

export const linkSchema = z.union([urlLinkSchema, mailtoLinkSchema]);

/** The names a node uses for its own link. Any other key is a child or a group, so these can't be slugs. */
export const FIELDS: ReadonlySet<string> = new Set([...Object.keys(urlFields), ...Object.keys(mailtoFields)]);

/** A child's key: a segment that isn't one of the link fields. */
const CHILD_PATTERN = new RegExp(`^(?!(?:${[...FIELDS].join("|")})$)${SEGMENT}$`);

/** A group's key: a segment in parentheses. */
const GROUP_PATTERN = new RegExp(`^\\(${SEGMENT}\\)$`);

/**
 * Messages for the checks that have none of their own. zod/mini loads no locale, so they
 * would otherwise all read "Invalid input".
 *
 * @param issue - The failed check
 * @returns The message, or `undefined` to keep the check's own
 */
function fieldError(issue: z.core.$ZodRawIssue): string | undefined {
  if (issue.code === "unrecognized_keys") {
    return `Not a field of this kind of link: ${issue.keys.map(key => `"${key}"`).join(", ")}.`;
  }

  if (issue.code === "invalid_type") {
    return issue.expected === "boolean" ? "Must be true or false." : `Must be a ${issue.expected}.`;
  }

  return undefined;
}

/**
 * Zod's report on a link's fields, each problem pointed at its place in the file.
 *
 * @param error - Zod's error for the link's fields
 * @param at - Where the link is in the file, such as `(design).dribbble`
 * @returns One message per problem
 */
function fieldIssues(error: z.core.$ZodError, at: string): string[] {
  // `cc[1]` for an item in a list, `.subject` for a field. Not Zod's own formatter: reaching
  // into `z.core` at run time would pull all of Zod into the Worker.
  const place = (path: readonly PropertyKey[]): string => path.map(part => typeof part === "number" ? `[${part}]` : `.${String(part)}`).join("");
  const issues = error.issues.map(({ message, path }) => `✖ ${message}\n  → at ${at}${place(path)}`);

  return [...new Set(issues)];
}

/**
 * The links from `links.json`, checked and flattened to their short paths. It runs in
 * `pnpm validate`, so a broken entry fails `pnpm check` (and the deploy) instead of a
 * visitor's click, and again when the Worker starts. Every problem is reported at once.
 *
 * @param input - The parsed JSON
 * @returns The links, by short path (`github/dx`)
 */
export function validateLinks(input: unknown): TLinks {
  if (!isObject(input)) {
    throw new Error("links.json is invalid:\n✖ It must hold an object of links.");
  }

  const issues: string[] = [];
  const found = new Map<string, { link: TLinks[string]; at: string }>();
  const issue = (message: string, at: string): void => {
    issues.push(`✖ ${message}\n  → at ${at}`);
  };

  /**
   * Records the link at one spot, after checking its fields, path length and uniqueness.
   *
   * @param fields - The link fields found at this spot (url, mailto, ...)
   * @param path - The short path's parts down to this spot
   * @param at - Where this spot is in the file, for messages
   * @param root - Whether this is the top level of the file
   * @param group - Whether this spot is a group
   * @param children - How many children and groups this spot holds
   */
  const addLink = (fields: Record<string, unknown>, path: readonly string[], at: string, root: boolean, group: boolean, children: number): void => {
    if (Object.keys(fields).length === 0) {
      if (children === 0 && !root) {
        issue(group ? "A group must hold links." : "Must be a link (url or mailto), or hold other links.", at);
      }

      return;
    }

    if (root || group) {
      issue(root ? "The top level can't be a link: put links under keys." : "A group only organizes links: it can't be a link itself.", at);

      return;
    }

    const short = path.join("/");
    const tooLong = short.length > MAX_PATH;

    if (tooLong) {
      issue(`${PATH_RULE} "${short}" is ${short.length}.`, at);
    }

    // The kind of link comes from its keys, so the problems reported are that kind's, not
    // a vague "matches neither kind".
    const isUrl = "url" in fields;

    if (isUrl === "mailto" in fields) {
      issue(isUrl ? "A link is either a url or a mailto, not both." : "A link needs a url or a mailto.", at);

      return;
    }

    const result = (isUrl ? urlLinkSchema : mailtoLinkSchema).safeParse(fields, { error: fieldError });

    if (!result.success) {
      issues.push(...fieldIssues(result.error, at));

      return;
    }

    const twin = found.get(short);

    if (twin !== undefined) {
      issue(`The short path "${short}" is defined twice; it is also at ${twin.at}.`, at);
    }
    else if (!tooLong) {
      found.set(short, { link: Object.freeze(result.data), at });
    }
  };

  const walk = (node: unknown, path: readonly string[], trail: readonly string[], group: boolean): void => {
    const root = trail.length === 0;
    const at = root ? "the top level" : trail.join(".");

    if (!isObject(node)) {
      issue(`Must be an object: a link, or a key that holds other links. (Link fields are ${[...FIELDS].join(", ")}.)`, at);

      return;
    }

    const fields: Record<string, unknown> = {};
    const children: Array<() => void> = [];

    for (const [key, value] of Object.entries(node)) {
      if (root && key === "$schema") {
        if (typeof value !== "string") {
          issue("Must be the path to links.schema.json.", key);
        }

        continue;
      }

      if (FIELDS.has(key)) {
        fields[key] = value;
      }
      else if (GROUP_PATTERN.test(key)) {
        children.push(() => walk(value, path, [...trail, key], true));
      }
      else if (CHILD_PATTERN.test(key)) {
        children.push(() => walk(value, [...path, key], [...trail, key], false));
      }
      else {
        // `__proto__` lands here too: it isn't a valid key, and it never reaches the map.
        issue(SEGMENT_RULE, [...trail, key].join("."));
      }
    }

    // The link here first, then the ones under it, so the map reads like the file.
    addLink(fields, path, at, root, group, children.length);

    for (const child of children) {
      child();
    }
  };

  walk(input, [], [], false);

  if (issues.length > 0) {
    throw new Error(`links.json is invalid:\n${issues.join("\n")}`);
  }

  return Object.freeze(Object.fromEntries([...found].map(([short, { link }]) => [short, link])));
}

/**
 * The JSON Schema editors use to check and autocomplete `links.json`: the same fields as
 * the checks above, on a tree of children and groups.
 *
 * @returns The schema
 */
export function linksJsonSchema(): Record<string, unknown> {
  const properties = (shape: z.core.$ZodShape): Record<string, unknown> => (z.toJSONSchema(z.object(shape)) as { properties: Record<string, unknown> }).properties;
  const keys = {
    patternProperties: {
      [CHILD_PATTERN.source]: { $ref: "#/$defs/node" },
      [GROUP_PATTERN.source]: { $ref: "#/$defs/group" },
    },
    additionalProperties: false,
  };

  return {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    title: "Redirector links",
    description: "The links served at to.ouss.es. A key extends the short path (github → dx is to.ouss.es/github/dx); a key in parentheses, like (design), only groups.",
    type: "object",
    // The `$schema` key that points editors here is allowed next to the links.
    properties: { $schema: { type: "string" } },
    ...keys,
    $defs: {
      node: {
        type: "object",
        description: "A link (url, or mailto for an email), links under it, or both.",
        properties: { ...properties(urlFields), ...properties(mailtoFields) },
        ...keys,
        minProperties: 1,
        dependentRequired: { permanent: ["url"], subject: ["mailto"], body: ["mailto"], cc: ["mailto"], bcc: ["mailto"] },
        dependentSchemas: { expires: { anyOf: [{ required: ["url"] }, { required: ["mailto"] }] } },
        not: {
          anyOf: [
            { required: ["url", "mailto"] },
            { required: ["permanent", "expires"], properties: { permanent: { const: true } } },
          ],
        },
      },
      group: {
        type: "object",
        description: "A group: it organizes the links in it without becoming part of their short paths.",
        ...keys,
        minProperties: 1,
      },
    },
  };
}

/**
 * When a link stops working, in milliseconds since the epoch. A bare day lasts through
 * its end, UTC.
 *
 * @param expires - The link's `expires` value
 * @returns The moment it expires, or `Infinity` when it never does
 */
export function expiresAt(expires: string | undefined): number {
  if (expires === undefined) {
    return Number.POSITIVE_INFINITY;
  }

  return /^\d{4}-\d{2}-\d{2}$/.test(expires) ? Date.parse(`${expires}T00:00:00Z`) + DAY_MS : Date.parse(expires);
}

/**
 * The links whose `expires` has passed. An expired link is not an error (it redirects to
 * the 404 page), so `pnpm validate` only warns about them.
 *
 * @param links - The links, by short path
 * @param now - The current time, in milliseconds since the epoch
 * @returns The expired paths, with their `expires` values
 */
export function expiredLinks(links: TLinks, now: number): Array<[slug: string, expires: string]> {
  return Object.entries(links).flatMap(([slug, link]) => link.expires !== undefined && expiresAt(link.expires) <= now ? [[slug, link.expires] as [string, string]] : []);
}
